window.AUTH=window.AUTH||{};window.AUTH["17-961"]={"d":"17-961","id":"2018/17-961","n":"Frank v. Gaos","briefs":[{"k":"petitioner","label":"Brief of petitioners Theodore H. Frank, et al.","date":"2018-07-09","url":"https://www.supremecourt.gov/DocketPDF/17/17-961/52594/20180709130345481_17-961BriefForPetitioners.pdf","side":"pet","n":73},{"k":"united-states","label":"Brief amicus curiae of United States in support of neither party","date":"2018-07-16","url":"https://www.supremecourt.gov/DocketPDF/17/17-961/54428/20180716192524453_17-961%20nsacUnitedStates.pdf","side":"us","n":44},{"k":"respondent","label":"Brief of respondents Paloma Gaos, et al.","date":"2018-08-29","url":"https://www.supremecourt.gov/DocketPDF/17/17-961/61145/20180829155754372_Gaos%20Respondents%20Brief%20and%20Appendix%20Combined.pdf","side":"res","n":71},{"k":"respondent","label":"Brief of respondent Google LLC","date":"2018-08-29","url":"https://www.supremecourt.gov/DocketPDF/17/17-961/61166/20180829194522714_17-961%20bs.pdf","side":"res","n":79},{"k":"reply","label":"Reply of petitioners Theodore H. Frank, et al.","date":"2018-09-28","url":"https://www.supremecourt.gov/DocketPDF/17/17-961/65143/20180928113001650_17-961ReplyBriefForPetitioners.pdf","side":"pet","n":52}],"opinion":"https://www.supremecourt.gov/opinions/18pdf/17-961_j42k.pdf","tr":true,"items":[{"t":"case","label":"Allen v. Bedolla","cite":"787 F.3d 1218","y":2015,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/787/1218/","by":{"0":"27"}},{"t":"case","label":"Amchem Prods., Inc. v. Windsor","cite":"521 U.S. 591","y":1997,"id":"1996/96-270","sc":1,"op":1,"ar":2,"sum":"In resolving the case the Court declined to reach the issue of whether the settlement proceeding was a justiciable case or controversy under Article III because, it held, determination of class certification was logically antecedent to these issues.","sumSrc":"Oyez","by":{"0":"1, 6, 20, 21","1":"2, 3, 4, 13, 25","2":"passim","3":"16","4":"4, 7"}},{"t":"case","label":"American Express Co. v. Italian Colors Restaurant","cite":"570 U.S. 333","y":2013,"id":"2012/12-133","sc":1,"sum":"The Court held that a clause prohibiting class action suits was enforceable even though it would cause costly arbitration.","sumSrc":"Oyez","by":{"0":"53"}},{"t":"case","label":"Arkansas Teacher Retirement Sys. v. State Street Bank & Trust Co.","cite":"232 F. Supp. 3d 189","y":2017,"court":"D. Mass.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/232/189/","by":{"0":"10"}},{"t":"case","label":"Back Doctors Ltd. v. Metropolitan Property & Cas. Ins. Co.","cite":"637 F.3d 827","y":2011,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/637/827/","by":{"0":"20","3":"21"}},{"t":"case","label":"Briseno v. ConAgra Foods, Inc.","cite":"844 F.3d 1121","y":2017,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/844/1121/","by":{"0":"35","3":"32, 33"}},{"t":"case","label":"Buckhannon Bd. & Care Home, Inc. v. W. Va. Dept. of Health & Human Resources","cite":"532 U.S. 598","y":2001,"id":"2000/99-1848","sc":1,"sum":"The Court held that the \"catalyst theory\" is not a permissible basis for the award of attorney's fees under the FHAA and ADA. \"In the United States, parties are ordinarily required to bear their own attorney's fees -- the prevailing party is not entitled to collect from the loser,\" wrote Chief Justice Rehnquist, \"[u]nder this 'American Rule,' we follow 'a general practice of not awarding fees to a prevailing party absent explicit statutory authority.'\" Dissenting, Justice Ruth Bader Ginsburg argued that \"Congress prescribed fee-shifting provisions like those included in the FHAA and ADA to encourage private enforcement of laws designed to advance civil rights.","sumSrc":"Oyez","by":{"0":"47"}},{"t":"case","label":"Campbell-Ewald Co. v. Gomez","cite":"136 S. Ct. 663","y":2016,"id":"2015/14-857","sc":1,"sum":"The Court held that an unaccepted settlement offer does not make a plaintiff’s claim moot, and a federal contractor does not have derivative sovereign liability from a suit under the Telephone Consumer Protection Act.","sumSrc":"Oyez","by":{"0":"1","1":"2"}},{"t":"case","label":"Caplin & Drysdale, Chartered v. United States","cite":"491 U.S. 617","y":1989,"id":"1988/87-1729","sc":1,"sum":"Christopher Reckmeyer was charged with running a massive drug importation and distribution scheme alleged to be a continuing criminal enterprise (CCE) in violation of 21 U. S. C. § 848. Relying on a portion of the CCE statute that authorizes forfeiture to the Government of property acquired as a result of drug-law violations, §853, the indictment sought forfeiture of specified assets in Reckmeyer's possession. The …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"33"}},{"t":"case","label":"China Agritech, Inc. v. Resh","cite":"138 S. Ct. 1800","y":2018,"id":"2017/17-432","sc":1,"sum":"The Court decided that upon denial of class certification, a putative class member may not, in lieu of promptly joining an existing suit or promptly filing a individual action, commence a class action anew beyond the time allowed by the applicable statute of limitations.","sumSrc":"Oyez","by":{"0":"1"}},{"t":"case","label":"City of Riverside v. Rivera","cite":"477 U.S. 561","y":1986,"id":"1985/85-224","sc":1,"sum":"Jr., the Court held, 5-4, that there was no requirement under Civil Rights Attorney's Fees Awards Act of 1976 that attorneys' fees be proportionate to the amount of damages a civil rights plaintiff might recover.","sumSrc":"Oyez","by":{"0":"46"}},{"t":"case","label":"Dennis v. Kellogg Co.","cite":"697 F.3d 858","y":2012,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/697/858/","sum":"Rejecting cy pres settlement of false-advertising claims that directed payments to charities that feed the needy because the cy pres organizations were not “dedicated to protecting consumers from, or redressing injuries caused by, false advertising”.","sumSrc":"brief:1","by":{"0":"23, 32","1":"25, 29"}},{"t":"case","label":"Devlin v. Scardelletti","cite":"536 U.S. 1","y":2002,"id":"2001/01-417","sc":1,"sum":"The Court held that nonnamed class members like Devlin, who have objected in a timely manner to approval of the settlement at the fairness hearing, have the power to bring an appeal without first intervening.","sumSrc":"Oyez","by":{"0":"3"}},{"t":"case","label":"District of Columbia v. Wesby","cite":"138 S. Ct. 577","y":2018,"id":"2017/15-1485","sc":1,"sum":"The Court decided that (1) officers had probable cause to arrest a number of partygoers for unlawful entry under D.C. law under the totality of the circumstances, and (2) that the officers were entitled to qualified immunity because their actions were not clearly unlawful at the time.","sumSrc":"Oyez","by":{"0":"47"}},{"t":"case","label":"Eubank v. Pella Corp.","cite":"753 F.3d 718","y":2014,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/753/718/","by":{"0":"22","2":"5"}},{"t":"case","label":"Farrar v. Hobby","cite":"506 U.S. 103","y":1992,"id":"1992/91-990","sc":1,"sum":"Petitioners, coadministrators of decedent Farrar's estate, sought $17 million in compensatory damages, pursuant to 42 U. S. C. §§ 1983 and 1985, from respondent Hobby and other Texas public officials for the alleged illegal closure of the school that Farrar and his son operated. However, the Federal District Court awarded them only nominal damages and, subsequently, awarded them $280,000 in attorney's fees under 42 …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"46, 47"}},{"t":"case","label":"Fraley v. Facebook, Inc.","cite":"966 F. Supp. 2d 939","y":2013,"court":"N.D. Cal.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/966/939/","by":{"0":"10–11, 42, 44","2":"44","3":"36"}},{"t":"case","label":"Gallego v. Northland Group","cite":"814 F.3d 123","y":2016,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/814/123/","by":{"0":"53","2":"45, 52"}},{"t":"case","label":"Gascho v. Global Fitness Holdings LLC","cite":"822 F.3d 269","y":2016,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/822/269/","by":{"0":"26, 27","4":"20"}},{"t":"case","label":"Hansberry v. Lee","cite":"311 U.S. 32","y":1940,"id":"scdb/1940-006","sc":1,"sum":"Numerous owners of lots in a particular area agreed in writing, each severally with each of the others, that their lots should not be sold to or occupied by Negroes, the effectiveness of the agreement being conditioned, however, upon signing by owners of a specified percentage of the lot frontage. In a case in a state court, tried upon an agreed statement of facts, in which it was stipulated (erroneously) that this …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"54","3":"15, 18"}},{"t":"case","label":"Harris v. Quinn","cite":"134 S. Ct. 2618","y":2014,"id":"2013/11-681","sc":1,"sum":"The Court held that the First Amendment prohibits the collection of union dues from home health care providers who do not wish to join a union.","sumSrc":"Oyez","by":{"0":"36"}},{"t":"case","label":"Hensley v. Eckerhart","cite":"461 U.S. 424","y":1983,"id":"1982/81-1244","sc":1,"sum":"The District Court did not properly consider the relationship between the extent of success and the amount of the attorney's fee award. The extent of a plaintiff's success is a crucial factor in determining the proper amount of an attorney's fee award under § 1988. Where the plaintiff failed to prevail on a claim unrelated to the successful claims, the hours spent on the unsuccessful claim should be excluded in …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"47"}},{"t":"case","label":"Hewitt v. Helms","cite":"482 U.S. 755","y":1987,"id":"1986/85-1630","sc":1,"sum":"Respondent is not a \"prevailing party\" eligible for attorney's fees under § 1988. A plaintiff must receive at least some relief on the merits of his claim before he can be said to \"prevail.\" Respondent obtained neither a damages award, injunction, or declaratory judgment, nor a consent decree, settlement, or other relief without benefit of a formal judgment.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"47"}},{"t":"case","label":"Houck v. Folding Carton Admin. Comm.","cite":"881 F.2d 494","y":1989,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/881/494/","by":{"0":"34"}},{"t":"case","label":"Ira Holtzman, CPA v. Turza","cite":"728 F.3d 682","y":2013,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/728/682/","by":{"0":"50","2":"32"}},{"t":"case","label":"Jackson v. Phillips","cite":"96 Mass. 539","y":1867,"url":"https://www.courtlistener.com/c/Mass./96/539/","by":{"0":"5"}},{"t":"case","label":"Keepseagle v. Perdue","cite":"856 F.3d 1039","y":2017,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/856/1039/","by":{"0":"39"}},{"t":"case","label":"Keyes v. Pacific Lumber Co.","cite":"51 F.3d 1449","y":1995,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/51/1449/","by":{"0":"56"}},{"t":"case","label":"Klier v. Elf Atochem N. Am., Inc.","cite":"658 F.3d 468","y":2011,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/658/468/","op":1,"sum":"Rejecting district court’s sua sponte redirection of settlement funds to cy pres.","sumSrc":"brief:3","by":{"0":"passim","1":"17, 18, 26, 27, 32","2":"passim","3":"26, 31, 47, 52","4":"18, 19"}},{"t":"case","label":"Knox v. SEIU, Local 1000","cite":"567 U.S. 298","y":2012,"id":"2011/10-1121","sc":1,"sum":"The Court found that, under the First Amendment, public-sector unions are not permitted to impose a special assessment fee without the consent of the member upon whom it is imposed.","sumSrc":"Oyez","by":{"0":"37","3":"28"}},{"t":"case","label":"Lane v. Facebook, Inc.","cite":"696 F.3d 811","y":2012,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/696/811/","by":{"0":"passim","1":"9","2":"9","3":"9, 10","4":"3"}},{"t":"case","label":"Marek v. Lane","cite":"134 S. Ct. 8","y":2013,"url":"https://www.courtlistener.com/c/S.%20Ct./134/8/","sc":1,"by":{"0":"28, 52"}},{"t":"case","label":"McDonough v. Toys “R” Us, Inc.","cite":"80 F. Supp. 3d 626","y":2015,"court":"E.D. Pa.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/80/626/","by":{"0":"42","2":"50","3":"34"}},{"t":"case","label":"McLaughlin v. American Tobacco Co.","cite":"522 F.3d 215","y":2008,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/522/215/","by":{"0":"35"}},{"t":"case","label":"Meinhard v. Salmon","cite":"249 N.Y. 458","y":1928,"url":"https://www.courtlistener.com/c/N.Y./249/458/","by":{"0":"55"}},{"t":"case","label":"Microsoft Corp. v. Baker","cite":"137 S. Ct. 1702","y":2017,"id":"2016/15-457","sc":1,"sum":"The Court determined that the federal courts of appeals lack jurisdiction to review an order denying class certification after the named plaintiffs have voluntarily dismissed their claims with prejudice.","sumSrc":"Oyez","by":{"0":"1, 48"}},{"t":"case","label":"Mirfasihi v. Fleet Mortg. Corp.","cite":"356 F.3d 781","y":2004,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/356/781/","sum":"Explaining that a cy pres class-action settlement is “badly misnamed”.","sumSrc":"brief:1","by":{"0":"33","1":"17, 19, 20, 24","3":"49"}},{"t":"case","label":"Molski v. Gleich","cite":"318 F.3d 937","y":2003,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/318/937/","by":{"0":"32"}},{"t":"case","label":"Nachshin v. AOL, LLC","cite":"663 F.3d 1034","y":2011,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/663/1034/","by":{"0":"38","2":"33, 47","3":"9, 30"}},{"t":"case","label":"Ortiz v. Fibreboard Corp.","cite":"527 U.S. 815","y":1999,"id":"1998/97-1704","sc":1,"sum":"The Court held that \"applicants for contested certification [of a mandatory settlement class on a limited fund theory under Rule 23(b)(1)(B)] must show that the fund is limited by more than the agreement of the parties, and has been allocated to claimants belonging within the class by a process addressing any conflicting interests of class members.\" \"The record on which the District Court rested its certification of the class for the purpose of the global settlement did not support the essential premises of mandatory limited fund actions.","sumSrc":"Oyez","by":{"0":"20","1":"12","2":"45","3":"16, 20, 23","4":"9, 16"}},{"t":"case","label":"Pearson v. NBTY, Inc.","cite":"772 F.3d 778","y":2014,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/772/778/","sum":"Finding no “justification” for reversion clause.","sumSrc":"brief:0","by":{"0":"passim","1":"4, 19, 25, 27, 28","4":"passim"}},{"t":"case","label":"Pearson v. Target Corp.,  F.3d ","cite":"2018 WL 3117848","y":2018,"court":"7th Cir. Jun. 26","by":{"0":"2, 10"}},{"t":"case","label":"Pecover v. Electronic Arts, Inc.","cite":"2013 WL 12121865","y":2013,"court":"N.D. Cal. May 30","by":{"0":"43","2":"44"}},{"t":"case","label":"Perdue v. Kenny A.","cite":"559 U.S. 542","y":2010,"id":"2009/08-970","sc":1,"sum":"The Court held that reasonable attorneys' fees awarded under a federal fee-shifting statute can be enhanced based on the quality of the attorney's performance and results obtained in exceptional circumstances.","sumSrc":"Oyez","by":{"0":"46","3":"56"}},{"t":"case","label":"Perkins v. Am. Nat’l Ins. Co.","cite":"2012 WL 2839788","y":2012,"court":"M.D. Ga. July 10","by":{"0":"34, 38"}},{"t":"case","label":"Pierce v. Visteon Corp.","cite":"791 F.3d 782","y":2015,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/791/782/","by":{"0":"51–52"}},{"t":"case","label":"Poertner v. Gillette Co.","cite":"618 F. App’x 624","y":2015,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/618/624/","by":{"0":"23, 24, 27"}},{"t":"case","label":"Redman v. RadioShack Corp.","cite":"768 F.3d 622","y":2014,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/768/622/","by":{"0":"39–40","4":"23"}},{"t":"case","label":"Rouse v. Hennepin County","cite":"2016 WL 3211814","y":2016,"court":"D. Minn. Jun. 9","by":{"0":"25"}},{"t":"case","label":"SEC v. Bear, Stearns & Co.","cite":"626 F. Supp. 2d 402","y":2009,"court":"S.D.N.Y.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/626/402/","by":{"0":"35, 37–38, 56"}},{"t":"case","label":"Shady Grove Orthopedic Assocs., P.A., v. Allstate Ins. Co.","cite":"559 U.S. 393","y":2010,"id":"2009/08-1008","sc":1,"sum":"The Court held that Section 901(b) of the New York Rules of Civil Procedure does not preclude a federal court ruling on entities from different jurisdictions from hearing a class action under Rule 23 of the Federal Rules of Civil Procedure.","sumSrc":"Oyez","by":{"0":"35, 47"}},{"t":"case","label":"Standard Fire Ins. Co. v. Knowles","cite":"568 U.S. 588","y":2013,"id":"2012/11-1450","sc":1,"sum":"The Court held that a plaintiff in a class action case cannot stipulate that the potential damages are less than $5 million in order to remove the case from federal jurisdiction.","sumSrc":"Oyez","by":{"0":"1, 20","3":"21"}},{"t":"case","label":"Sullivan v. DB Investments","cite":"667 F.3d 273","y":2011,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/667/273/","by":{"0":"27, 51, 52","2":"39","3":"25, 34, 35"}},{"t":"case","label":"Tyson Foods Inc. v. Bouaphakeo","cite":"136 S. Ct. 1036","y":2016,"id":"2015/14-1146","sc":1,"sum":"The Court determined that a class action is properly certified and maintained, despite differences among the plaintiff class, if all the individual plaintiffs' cases ask the same central question and even if some plaintiffs were not injured and have no legal right to damages.","sumSrc":"Oyez","by":{"0":"38","1":"2, 12","3":"41"}},{"t":"case","label":"United States v. Carter","cite":"217 U.S. 286","y":1910,"id":"scdb/1909-135","sc":1,"sum":"Where both the courts below have concurred upon material facts, the burden rests bn the appellant to satisfy this court that such conclusions are erroneous.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"55"}},{"t":"case","label":"Wendt v. Fischer","cite":"243 N.Y. 439","y":1926,"url":"https://www.courtlistener.com/c/N.Y./243/439/","by":{"0":"55"}},{"t":"case","label":"Wilson v. EverBank, N.A.","cite":"2016 WL 457011","y":2016,"court":"S.D. Fla. Feb. 3","by":{"0":"27"}},{"t":"case","label":"Wright v. United States","cite":"732 F.2d 1048","y":1984,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/732/1048/","by":{"0":"55"}},{"t":"case","label":"Young v. United States ex rel. Vuitton et Fils SA","cite":"481 U.S. 787","y":1987,"id":"1986/85-1329","sc":1,"sum":"The judgment is reversed. 780 F. 2d 179, reversed.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"54"}},{"t":"const","label":"Article III","clauses":[["judicial-vesting","Judicial Vesting Clause"],["cases-controversies","Cases or Controversies (Justiciability)"],["original-jurisdiction","Original and Appellate Jurisdiction"],["treason","Treason Clause"]],"by":{"0":"8","1":"passim","2":"22, 38, 39, 55","4":"25, 26"}},{"t":"usc","label":"18 U.S.C. § 2707","url":"https://www.law.cornell.edu/uscode/text/18/2707","subs":["(c)","(a)"],"stext":{"head":"§2707. Civil action","paras":[[0,"(a) Cause of Action.—Except as provided in section 2703(e), any provider of electronic communication service, subscriber, or other person aggrieved by any violation of this chapter in which the conduct constituting the violation is engaged in with a knowing or intentional state of mind may, in a civil action, recover from the person or entity, other than the United States, which engaged in that violation such relief as may be appropriate."],[0,"(b) Relief.—In a civil action under this section, appropriate relief includes—"],[1,"(1) such preliminary and other equitable or declaratory relief as may be appropriate;"],[1,"(2) damages under subsection (c); and"],[1,"(3) a reasonable attorney's fee and other litigation costs reasonably incurred."],[0,"(c) Damages.—The court may assess as damages in a civil action under this section the sum of the actual damages suffered by the plaintiff and any profits made by the violator as a result of the violation, but in no case shall a person entitled to recover receive less than the sum of $1,000. If the violation is willful or intentional, the court may assess punitive damages. In the case of a successful action to enforce liability under this section, the court may assess the costs of the action, together with reasonable attorney fees determined by the court."],[0,"(d) Administrative Discipline.—If a court or appropriate department or agency determines that the United States or any of its departments or agencies has violated any provision of this chapter, and the court or appropriate department or agency finds that the circumstances surrounding the violation raise serious questions about whether or not an officer or employee of the United States acted willfully or intentionally with respect to the violation, the department or agency shall, upon receipt of a true and correct copy of the decision and findings of the court or appropriate department or agency promptly initiate a proceeding to determine whether disciplinary action against the officer or employee is warranted. If the head of the department or agency involved determines that disciplinary action is not warranted, he or she shall notify the Inspector General with jurisdiction over the department or agency concerned and shall provide the Inspector General with the reasons for such determination."],[0,"(e) Defense.—A good faith reliance on—"],[1,"(1) a court warrant or order, a grand jury subpoena, a legislative authorization, or a statutory authorization (including a request of a governmental entity under section 2703(f) of this title);"],[1,"(2) a request of an investigative or law enforcement officer under section 2518(7) of this title; or"],[1,"(3) a good faith determination that section 2511(3), section 2702(b)(9), or section 2702(c)(7) of this title permitted the conduct complained of;"],[0,"is a complete defense to any civil or criminal action brought under this chapter or any other law."],[0,"(f) Limitation.—A civil action under this section may not be commenced later than two years after the date upon which the claimant first discovered or had a reasonable opportunity to discover the violation."],[0,"(g) Improper Disclosure.—Any willful disclosure of a \"record\", as that term is defined in section 552a(a) of title 5, United States Code, obtained by an investigative or law enforcement officer, or a governmental entity, pursuant to section 2703 of this title, or from a device installed pursuant to section 3123 or 3125 of this title, that is not a disclosure made in the proper performance of the official functions of the officer or governmental entity making the disclosure, is a violation of this chapter. This provision shall not apply to information previously lawfully disclosed (prior to the commencement of any civil or administrative proceeding under this chapter) to the public by a Federal, State, or local governmental entity or by the plaintiff in a civil action under this chapter."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/2707?type=usc&year=mostrecent&link-type=html"},"head":"§2707. Civil action","tname":"Crimes and Criminal Procedure","by":{"0":"5, 8, 53","1":"3, 3","3":"39"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"3"}},{"t":"usc","label":"28 U.S.C. § 2042","url":"https://www.law.cornell.edu/uscode/text/28/2042","by":{"0":"51"}},{"t":"usc","label":"28 U.S.C. § 2072","url":"https://www.law.cornell.edu/uscode/text/28/2072","subs":["(b)"],"stext":{"head":"§2072. Rules of procedure and evidence; power to prescribe","paras":[[0,"(a) The Supreme Court shall have the power to prescribe general rules of practice and procedure and rules of evidence for cases in the United States district courts (including proceedings before magistrate judges thereof) and courts of appeals."],[0,"(b) Such rules shall not abridge, enlarge or modify any substantive right. All laws in conflict with such rules shall be of no further force or effect after such rules have taken effect."],[0,"(c) Such rules may define when a ruling of a district court is final for the purposes of appeal under section 1291 of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2072?type=usc&year=mostrecent&link-type=html"},"head":"§2072. Rules of procedure and evidence; power to prescribe","tname":"Judiciary and Judicial Procedure","by":{"0":"33","3":"13, 18, 24, 24"}},{"t":"usc","label":"42 U.S.C. § 1983","url":"https://www.law.cornell.edu/uscode/text/42/1983","by":{"0":"46, 47"}},{"t":"usc","label":"42 U.S.C. § 1988","url":"https://www.law.cornell.edu/uscode/text/42/1988","by":{"0":"46, 47"}},{"t":"rule","label":"Fed. R. Civ. P. 23","url":"https://www.law.cornell.edu/rules/frcp/rule_23","subs":["(a)(4)","(b)(3)","(e)","(e)(2)","(g)(4)","(h)","(a)(1)","(a)(2)","(b)(1)","(e)(2)(C)(ii)","(e)(2)(C)(iii)","(e)(4)","(a)(3)","(b)(1)(B)","(b)(2)","(d)","(f)"],"by":{"0":"passim, 4, 20, 53, 54, passim, passim, 4, 4, 20, 4, 40, 56","2":"27, 25, 41, 45, 42","3":"passim, 17, 17, 17, 22, passim, passim, 31, 37, 30, 55, 27","4":"passim, 26, 26, 4, 16, 4, 17, 4, passim, 4, 7, 18, 3, 19"}},{"t":"case","label":"Amgen Inc. v. Connecticut Ret. Plans & Trust Funds","cite":"568 U.S. 455","y":2013,"id":"2012/11-1085","sc":1,"sum":"The Court held that during class certification, the court does not need proof of materiality and does not have to allow the defendant to present evidence to rebut the certification.","sumSrc":"Oyez","by":{"1":"2","2":"3, 24, 30","4":"5"}},{"t":"case","label":"Arizonans for Official English v. Arizona","cite":"520 U.S. 43","y":1997,"id":"1996/95-974","sc":1,"ar":1,"sum":"Announced by Justice Ruth Bader Ginsburg, the Court held that the dispute was moot due to the previous resignation of Yniguez. The Court did not rule on the constitutionality of the article.","sumSrc":"Oyez","by":{"1":"11","4":"27"}},{"t":"case","label":"Califano v. Yamasaki","cite":"442 U.S. 682","y":1979,"id":"1978/77-1511","sc":1,"sum":"Section 204 (a) (1) of the Social Security Act (Act) authorizes the Secretary of the Department of Health, Education, and Welfare to recoup erroneous overpayments made to a beneficiary under the old-age, survivors', or disability insurance programs by decreasing future payments to which the overpaid person is entitled. However, § 204 (b) commands that \"there shall be no adjustment of payments to, or recovery by the …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"23","2":"3, 39"}},{"t":"case","label":"Central States Se. & Sw. Areas Health & Welfare Fund v. Merck-Medco Managed Care, L.L.C.","cite":"433 F.3d 181","y":2005,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/433/181/","by":{"1":"12"}},{"t":"case","label":"City of Los Angeles v. Lyons","cite":"461 U.S. 95","y":1983,"id":"1982/81-1064","sc":1,"sum":"In a 5-to-4 decision, the Court held that federal courts were without jurisdiction to entertain Lyons' claim for injunctive relief.","sumSrc":"Oyez","by":{"1":"23, 25","2":"39"}},{"t":"case","label":"Edwards v. First Am. Corp.","cite":"610 F.3d 514","y":2010,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/610/514/","op":2,"by":{"1":"6, 13, 14","3":"5"}},{"t":"case","label":"Friends of the Earth, Inc. v. Laidlaw Envtl. Servs. (TOC), Inc.","cite":"528 U.S. 167","y":2000,"id":"1999/98-822","sc":1,"op":1,"sum":"The Court held that a citizen suitor's claim for civil penalties need not be dismissed as moot when the defendant, after commencement of the litigation, has come into compliance with its NPDES permit. \"A defendant's voluntary cessation of allegedly unlawful conduct ordinarily does not suffice to moot a case,\" Justice Ginsburg wrote for the Court. \"Congress has found that civil penalties in the Clean Water Act cases do more than promote immediate compliance... they also deter future violations,\" concluded Justice Ginsburg.","sumSrc":"Oyez","by":{"1":"11, 23, 24","2":"38"}},{"t":"case","label":"Gill v. Whitford","cite":"138 S. Ct. 1916","y":2018,"id":"2017/16-1161","sc":1,"sum":"A case in which the Court was asked to decide whether partisan gerrymandering claims are justiciable, but the Court held that the plaintiffs lacked judicial standing.","sumSrc":"Oyez","by":{"1":"23","2":"39"}},{"t":"case","label":"International Precious Metals Corp. v. Waters","cite":"530 U.S. 1223","y":2000,"url":"https://supreme.justia.com/cases/federal/us/530/1223/","sc":1,"by":{"1":"29"}},{"t":"case","label":"Jones v. National Distillers","cite":"56 F. Supp. 2d 355","y":1999,"court":"S.D.N.Y.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/56/355/","by":{"1":"25"}},{"t":"case","label":"Kokkonen v. Guardian Life Ins. Co. of Am.","cite":"511 U.S. 375","y":1994,"id":"1993/93-263","sc":1,"sum":"A federal district court, possessing only that power authorized by Constitution and statute, lacks jurisdiction over a claim for breach of a contract, part of the consideration for which was dismissal of an earlier federal suit. No federal statute makes that connection (if it constitutionally could) the basis for federal-court jurisdiction over the contract dispute. Moreover, the doctrine of ancillary jurisdiction …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"12","3":"26"}},{"t":"case","label":"Kremens v. Bartley","cite":"431 U.S. 119","y":1977,"id":"1976/75-1064","sc":1,"sum":"Appellees, five mentally ill individuals who were between 15 and 18 years old at the time the complaint was filed, were the named plaintiffs m an action challenging the constitutionality of a 1966 Pennsylvania statute governing the voluntary admission and voluntary commitment to state mental health institutions of persons aged 18 or younger. Appellees sought to vindicate their constitutional rights and to represent …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"15"}},{"t":"case","label":"Kritzer v. Safelite Sols., LLC","cite":"2012 WL 1945144","y":2012,"court":"S.D. Ohio May 30","by":{"1":"25"}},{"t":"case","label":"Lewis v. Casey","cite":"518 U.S. 343","y":1996,"id":"1995/94-1511","sc":1,"sum":"The Court held that the success of Casey's systemic challenge was dependent on the ability to show widespread actual injury, and the District Court's failure to identify anything more than isolated instances of actual injury rendered its finding of a systemic Bounds violation invalid.","sumSrc":"Oyez","by":{"1":"23"}},{"t":"case","label":"Lujan v. Defenders of Wildlife","cite":"504 U.S. 555","y":1992,"id":"1991/90-1424","sc":1,"sum":"Even if the Court were to assume that the agency-funded projects at issue threatened listed species, there was no proof that these actions would produce \"actual or imminent\" injuries to particular respondents who might some day wish to visit the foreign countries in question.","sumSrc":"Oyez","by":{"1":"23","2":"38"}},{"t":"case","label":"Mace v. Van Ru Credit Corp.","cite":"109 F.3d 338","y":1997,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/109/338/","by":{"1":"27","3":"33"}},{"t":"case","label":"Marek v. Lane","cite":"571 U.S. 1003","y":2013,"url":"https://supreme.justia.com/cases/federal/us/571/1003/","sc":1,"by":{"1":"6, 18","3":"9, 29, 30, 51"}},{"t":"case","label":"Robins v. Spokeo, Inc.","cite":"867 F.3d 1108","y":2017,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/867/1108/","sum":"Finding, on remand from this Court, that plaintiffs’ asserted injury under federal consumer privacy statute was sufficiently concrete to support standing.","sumSrc":"brief:1","by":{"1":"15","3":"32","4":"26"}},{"t":"case","label":"Spokeo, Inc. v. Robins","cite":"136 S. Ct. 1540","y":2016,"id":"2015/13-1339","sc":1,"sum":"The Court held that lower courts need to consider the elements of Article III standing analysis separately in determining whether standing is sufficient for a federal court to hear the case.","sumSrc":"Oyez","by":{"1":"10, 13, 14","2":"54, 55, 56","3":"5, 32, 46","4":"25, 26"}},{"t":"case","label":"Steel Co. v. Citizens for a Better Env’t","cite":"523 U.S. 83","y":1998,"id":"1997/96-643","sc":1,"sum":"The Court held, because none of the relief sought would likely remedy its alleged injury in fact, that Citizens For A Better Environment lacked standing to maintain suit and that the Court and lower federal courts lack the jurisdiction to entertain it. While all nine Justices agreed that the organization lacked standing, they disagreed on the reasons.","sumSrc":"Oyez","by":{"1":"11, 23","2":"38"}},{"t":"case","label":"Summers v. Earth Island Inst.","cite":"555 U.S. 488","y":2009,"id":"2008/07-463","sc":1,"sum":"The Court held that the defendants did not have standing to challenge regulations of the U.S. Forest Service in the absence of a live dispute over the application of those regulations.","sumSrc":"Oyez","by":{"1":"25"}},{"t":"case","label":"United States v. Sanchez-Gomez","cite":"138 S. Ct. 1532","y":2018,"id":"2017/17-312","sc":1,"sum":"The Court held that challenges to the federal district-wide policy of using of pretrial physical restraints are moot.","sumSrc":"Oyez","by":{"1":"23","2":"38"}},{"t":"law","label":"Pub. L. No. 109-2","url":"https://www.govinfo.gov/link/plaw/109/public/2","by":{"1":"30"}},{"t":"usc","label":"18 U.S.C. § 2701","url":"https://www.law.cornell.edu/uscode/text/18/2701","subs":["(c)(2)"],"stext":{"head":"§2701. Unlawful access to stored communications","paras":[[0,"(a) Offense.—Except as provided in subsection (c) of this section whoever—"],[1,"(1) intentionally accesses without authorization a facility through which an electronic communication service is provided; or"],[1,"(2) intentionally exceeds an authorization to access that facility;"],[0,"and thereby obtains, alters, or prevents authorized access to a wire or electronic communication while it is in electronic storage in such system shall be punished as provided in subsection (b) of this section."],[0,"(b) Punishment.—The punishment for an offense under subsection (a) of this section is—"],[1,"(1) if the offense is committed for purposes of commercial advantage, malicious destruction or damage, or private commercial gain, or in furtherance of any criminal or tortious act in violation of the Constitution or laws of the United States or any State—"],[2,"(A) a fine under this title or imprisonment for not more than 5 years, or both, in the case of a first offense under this subparagraph; and"],[2,"(B) a fine under this title or imprisonment for not more than 10 years, or both, for any subsequent offense under this subparagraph; and"],[1,"(2) in any other case—"],[2,"(A) a fine under this title or imprisonment for not more than 1 year or both, in the case of a first offense under this paragraph; and"],[2,"(B) a fine under this title or imprisonment for not more than 5 years, or both, in the case of an offense under this subparagraph that occurs after a conviction of another offense under this section."],[0,"(c) Exceptions.—Subsection (a) of this section does not apply with respect to conduct authorized—"],[1,"(1) by the person or entity providing a wire or electronic communications service;"],[1,"(2) by a user of that service with respect to a communication of or intended for that user; or"],[1,"(3) in section 2703, 2704 or 2518 of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/2701?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§2701. Unlawful access to stored communications","tname":"Crimes and Criminal Procedure","by":{"1":"6","3":"4","4":"14"}},{"t":"usc","label":"18 U.S.C. § 2702","url":"https://www.law.cornell.edu/uscode/text/18/2702","subs":["(a)(1)","(a)(2)"],"by":{"1":"3, 3"}},{"t":"usc","label":"28 U.S.C. § 1712","url":"https://www.law.cornell.edu/uscode/text/28/1712","subs":["(a)","(b)","(e)"],"stext":{"head":"§1712. Coupon settlements","paras":[[0,"(a) Contingent Fees in Coupon Settlements.—If a proposed settlement in a class action provides for a recovery of coupons to a class member, the portion of any attorney's fee award to class counsel that is attributable to the award of the coupons shall be based on the value to class members of the coupons that are redeemed."],[0,"(b) Other Attorney's Fee Awards in Coupon Settlements.—"],[1,"(1) In general.—If a proposed settlement in a class action provides for a recovery of coupons to class members, and a portion of the recovery of the coupons is not used to determine the attorney's fee to be paid to class counsel, any attorney's fee award shall be based upon the amount of time class counsel reasonably expended working on the action."],[1,"(2) Court approval.—Any attorney's fee under this subsection shall be subject to approval by the court and shall include an appropriate attorney's fee, if any, for obtaining equitable relief, including an injunction, if applicable. Nothing in this subsection shall be construed to prohibit application of a lodestar with a multiplier method of determining attorney's fees."],[0,"(c) Attorney's Fee Awards Calculated on a Mixed Basis in Coupon Settlements.—If a proposed settlement in a class action provides for an award of coupons to class members and also provides for equitable relief, including injunctive relief—"],[1,"(1) that portion of the attorney's fee to be paid to class counsel that is based upon a portion of the recovery of the coupons shall be calculated in accordance with subsection (a); and"],[1,"(2) that portion of the attorney's fee to be paid to class counsel that is not based upon a portion of the recovery of the coupons shall be calculated in accordance with subsection (b)."],[0,"(d) Settlement Valuation Expertise.—In a class action involving the awarding of coupons, the court may, in its discretion upon the motion of a party, receive expert testimony from a witness qualified to provide information on the actual value to the class members of the coupons that are redeemed."],[0,"(e) Judicial Scrutiny of Coupon Settlements.—In a proposed settlement under which class members would be awarded coupons, the court may approve the proposed settlement only after a hearing to determine whether, and making a written finding that, the settlement is fair, reasonable, and adequate for class members. The court, in its discretion, may also require that a proposed settlement agreement provide for the distribution of a portion of the value of unclaimed coupons to 1 or more charitable or governmental organizations, as agreed to by the parties. The distribution and redemption of any proceeds under this subsection shall not be used to calculate attorneys' fees under this section."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1712?type=usc&year=mostrecent&link-type=html"},"head":"§1712. Coupon settlements","tname":"Judiciary and Judicial Procedure","by":{"1":"3, 3, 3","4":"5"}},{"t":"usc","label":"28 U.S.C. § 1715","url":"https://www.law.cornell.edu/uscode/text/28/1715","subs":["(b)","(d)"],"by":{"1":"3, 3, 3"}},{"t":"case","label":"Adarand Constructors, Inc. v. Mineta","cite":"534 U.S. 103","y":2001,"id":"2001/00-730","sc":1,"sum":"After Adarand asserted that it was only challenging the rules pertaining to the direct procurement of DOT funds for highway construction on federal lands rather than any part of the DOT's DBE program as it pertained to state and local procurement, the Court concluded that the posture of the case had changed.","sumSrc":"Oyez","by":{"2":"54, 55"}},{"t":"case","label":"Arizona v. Hicks","cite":"480 U.S. 321","y":1987,"id":"1986/85-1027","sc":1,"sum":"The Court found that the search and seizure of the stereo equipment violated the Fourth and Fourteenth Amendments. Citing the Court's holding in Coolidge v. New Hampshire (1971), Justice Scalia upheld the \"plain view\" doctrine which allows police officers under some circumstances to seize evidence in plain view without a warrant.","sumSrc":"Oyez","by":{"2":"56"}},{"t":"case","label":"ATD Grp. v. Frank","cite":"2017 WL 4014951","y":2017,"court":"2d Cir. Mar. 29","by":{"2":"47"}},{"t":"case","label":"Bay Area Laundry & Dry Cleaning Pension Tr. Fund v. Ferbar Corp. of Cal., Inc.","cite":"522 U.S. 192","y":1997,"id":"1997/96-370","sc":1,"sum":"The Court held that the MPPAA's six-year statute of limitations on a pension fund's action to collect unpaid withdrawal liability does not begin to run until the employer fails to make a payment on the schedule set by the fund.","sumSrc":"Oyez","by":{"2":"37"}},{"t":"case","label":"Beastie Boys v. Monster Energy Co.","cite":"983 F. Supp. 2d 369","y":2014,"court":"S.D.N.Y.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/983/369/","ar":1,"by":{"2":"28"}},{"t":"case","label":"Beech Aircraft Corp. v. Rainey","cite":"488 U.S. 153","y":1988,"id":"1988/87-981","sc":1,"sum":"Respondents' spouses, a Navy flight instructor and her student, were killed when, during training exercises, their Navy aircraft banked sharply to avoid another plane, lost altitude, and crashed. At the trial of respondents' product liability suit against petitioners, the companies which manufactured and serviced the plane in question, the only seriously disputed issue was whether the crash was caused by pilot error …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"25"}},{"t":"case","label":"Boeing Co. v. Van Gemert","cite":"444 U.S. 472","y":1980,"id":"1979/78-1327","sc":1,"sum":"Petitioner company called for the redemption of certain convertible debentures, fixing a date by which debenture holders could convert their debentures into shares of petitioner's stock and after which debenture holders could only redeem their debentures for slightly more than face value. After the deadline expired, some of the nonconverting debenture holders brought a class action against petitioner, claiming that …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"41, 42","3":"22","4":"2, 20"}},{"t":"case","label":"Page(s) \u0003 Bowen v. Massachusetts","cite":"487 U.S. 879","y":1988,"id":"1987/87-712","sc":1,"sum":"The federal contribution (referred to as a \"reimbursement\") to a State's Medicaid program takes the form of advances based on the State's estimate of its future expenditures for covered services. Overpayments may be withheld from future advances, or, if a disallowance dispute develops, may be retained by the State at its option pending resolution of the dispute. After Massachusetts was reimbursed by the Department …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"39"}},{"t":"case","label":"Caperton v. A. T. Massey Coal Co.","cite":"556 U.S. 868","y":2009,"id":"2008/08-22","sc":1,"sum":"The Court held that the Due Process Clause of the 14th Amendment required that a justice recuse himself from a case if one of the parties in the suit donated $3 million to the justice's election campaign.","sumSrc":"Oyez","by":{"2":"46"}},{"t":"case","label":"Carnegie v. Household Int’l, Inc.","cite":"376 F.3d 656","y":2004,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/376/656/","by":{"2":"36"}},{"t":"case","label":"Carpenter v. United States","cite":"138 S. Ct. 2206","y":2018,"id":"2017/16-402","sc":1,"sum":"The Court held that the warrantless seizure and search of cell phone records revealing the location and movements of a cell phone user over the course of 127 days violates the Fourth Amendment.","sumSrc":"Oyez","by":{"2":"56"}},{"t":"case","label":"Christian Legal Soc’y Chapter of Univ. of Cal. v. Martinez","cite":"561 U.S. 661","y":2010,"id":"2009/08-1371","sc":1,"sum":"The Court held that a college's mandate requiring all officially-recognized student organizations be inclusive and welcoming to all students did not violate a group of Christian students' First Amendment rights when the college refused to recognize a student group that required all members to sign a statement of Christian beliefs for membership.","sumSrc":"Oyez","by":{"2":"38"}},{"t":"case","label":"Connick v. Thompson","cite":"563 U.S. 51","y":2011,"id":"2010/09-571","sc":1,"sum":"The Court held that a prosecutor's office cannot be held liable for the illegal conduct of one of its employees when there has only been one violation resulting from allegedly deficient training.","sumSrc":"Oyez","by":{"2":"43"}},{"t":"case","label":"Eisen v. Carlisle","cite":"417 U.S. 156","y":1974,"id":"1973/73-203","sc":1,"sum":"Petitioner brought a class action under Fed. Rule Civ. Proc. 23 on behalf of himself and all odd-lot traders on the New York Stock Exchange for a certain four-year period, charging respondent brokerage firms, which handled 99% of the Exchange's odd-lot business, and respondent Exchange with violating the antitrust and securities laws. There followed a series of decisions by the District Court and the Court of …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"37"}},{"t":"case","label":"Evans v. Jeff D.","cite":"475 U.S. 717","y":1986,"id":"1985/84-1288","sc":1,"sum":"The Civil Rights Attorney's Fees Awards Act of 1976 (Fees Act) provides that \"the court, in its discretion, may allow the prevailing party... a reasonable attorney's fee\" in enumerated civil rights actions. Respondents brought a class action against petitioners (the Governor and other public officials of Idaho responsible for the education and treatment of mentally handicapped children) in Federal District Court on …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"25","3":"52"}},{"t":"case","label":"Fischel v. Equitable Life Assurance Soc’y of U.S.","cite":"307 F.3d 997","y":2002,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/307/997/","by":{"2":"54"}},{"t":"case","label":"Fox v. Vice","cite":"563 U.S. 826","y":2011,"id":"2010/10-114","sc":1,"sum":"The Court held that a court may award attorney's fees to civil rights defendants when the plaintiff's suit involves frivolous and non-frivolous claims, but only for the costs incurred due to the frivolous claims.","sumSrc":"Oyez","by":{"2":"54","4":"6"}},{"t":"case","label":"Glover v. United States","cite":"531 U.S. 198","y":2001,"id":"2000/99-8576","sc":1,"sum":"The Court held that Court of appeals erred in engrafting onto the prejudice branch of the Strickland test the requirement that any increase in sentence must meet a standard of significance. Thus, the denial of Glover's motion to correct his sentence was reversed and remanded.","sumSrc":"Oyez","by":{"2":"37"}},{"t":"case","label":"Granite Rock Co. v. Int’l Bhd. of Teamsters","cite":"561 U.S. 287","y":2010,"id":"2009/08-1214","sc":1,"sum":"The Court held that federal courts have jurisdiction to determine whether or not a collective bargaining agreement was formed between two parties when the agreement is disputed, but neither party makes a challenge to the arbitration clause contained in the agreement.","sumSrc":"Oyez","by":{"2":"37"}},{"t":"case","label":"Guidry v. Sheet Metal Workers Nat’l Pension Fund","cite":"493 U.S. 365","y":1990,"id":"1989/88-1105","sc":1,"sum":"The constructive trust violates ERISA's prohibition on assignment or alienation of pension benefits.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"26"}},{"t":"case","label":"Hanlon v. Chrysler Corp.","cite":"150 F.3d 1011","y":1998,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/150/1011/","by":{"2":"45","3":"38"}},{"t":"case","label":"Hughes v. Kore of Ind. Enter., Inc.","cite":"731 F.3d 672","y":2013,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/731/672/","by":{"2":"8, 31, 32, 33","4":"20"}},{"t":"case","label":"Izumi Seimitsu Kogyo Kabushiki Kaisha v. U.S. Philips Corp.","cite":"510 U.S. 27","y":1993,"id":"1993/92-1123","sc":1,"sum":"Petitioner Izumi Seimitsu Kogyo Kabushiki Kaisha was a party at the first trial in an action brought against it and respondent Windmere Corporation by respondent U. S. Philips Corporation, but was not a party to the second trial, in which Windmere prevailed. While the judgments from the second trial were on appeal, respondents reached a settlement and filed a joint motion to vacate the District Court's judgments. …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"54"}},{"t":"case","label":"Kellogg Brown & Root Servs., Inc. v. United States ex rel. Carter","cite":"135 S. Ct. 1970","y":2015,"url":"https://www.courtlistener.com/c/S.%20Ct./135/1970/","sc":1,"by":{"2":"25"}},{"t":"case","label":"Koby v. ARS Nat’l Servs., Inc.","cite":"846 F.3d 1071","y":2017,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/846/1071/","by":{"2":"44"}},{"t":"case","label":"Low v. LinkedIn Corp.","cite":"900 F. Supp. 2d 1010","y":2012,"court":"N.D. Cal.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/900/1010/","by":{"2":"12"}},{"t":"case","label":"Lytle v. Household Mfg., Inc.","cite":"494 U.S. 545","y":1990,"id":"1989/88-334","sc":1,"sum":"Petitioner Lytle, an Afro-American, filed an action under both Title VII of the Civil Rights Act of 1964 and 42 U. S. C. § 1981, alleging that respondent Schwitzer Turbochargers had terminated his employment because of his race and had retaliated against him for filing a charge with the Equal Employment Opportunity Commission by subsequently providing inadequate references to prospective employers. He requested a …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"41"}},{"t":"case","label":"Marshall v. Nat’l Football League","cite":"787 F.3d 502","y":2015,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/787/502/","by":{"2":"39","3":"24"}},{"t":"case","label":"Masters v. Wilhelmina Model Agency, Inc.","cite":"473 F.3d 423","y":2007,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/473/423/","by":{"2":"31","3":"19, 31, 33"}},{"t":"case","label":"Miller v. Steinbach","cite":"1974 WL 350","y":1974,"court":"S.D.N.Y. Jan. 3","by":{"2":"8","3":"21","4":"16"}},{"t":"case","label":"\u0003 \u0003 \u0003 Nat’l Ass’n of Chain Drug Stores v. New Eng. Carpenters Health Benefits Fund","cite":"582 F.3d 30","y":2005,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/582/30/","by":{"2":"25"}},{"t":"case","label":"New York v. Reebok Int’l Ltd.","cite":"96 F.3d 44","y":1996,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/96/44/","by":{"2":"8, 32","3":"31","4":"19"}},{"t":"case","label":"Nix v. Whiteside","cite":"475 U.S. 157","y":1986,"id":"1985/84-1321","sc":1,"sum":"The Sixth Amendment right of a criminal defendant to assistance of counsel is not violated when an attorney refuses to cooperate with the defendant in presenting perjured testimony at his trial.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"43"}},{"t":"case","label":"Phillips Petrol. Corp. v. Shutts","cite":"472 U.S. 797","y":1985,"id":"1984/84-233","sc":1,"sum":"During the 1970's, petitioner produced or purchased natural gas from leased land located in 11 States. Respondents, royalty owners possessing rights to leases from which petitioner produced the gas, brought a class action against petitioner in a Kansas state court, seeking to recover interest on royalty payments that had been delayed by petitioner. The trial court certified a class consisting of 33,000 royalty …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"35, 38","3":"27, 28"}},{"t":"case","label":"Polar Int’l Brokerage Corp. v. Reeve","cite":"187 F.R.D. 108","y":1999,"court":"S.D.N.Y.","url":"https://www.courtlistener.com/c/F.R.D./187/108/","by":{"2":"44"}},{"t":"case","label":"Powell v. Ga.-Pac. Corp.","cite":"119 F.3d 703","y":1997,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/119/703/","by":{"2":"8, 32","3":"20, 31, 47"}},{"t":"case","label":"Sebelius v. Cloer","cite":"569 U.S. 369","y":2013,"id":"2012/12-236","sc":1,"sum":"The Court found that a person who petitions under the National Childhood Vaccine Injury Act can recover attorney's fees regardless of if the petition was ultimately successful.","sumSrc":"Oyez","by":{"2":"44"}},{"t":"case","label":"Six (6) Mexican Workers v. Ariz. Citrus Growers","cite":"904 F.2d 1301","y":1990,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/904/1301/","by":{"2":"passim"}},{"t":"case","label":"Synfuel Techs., Inc. v. DHL Express (USA), Inc.","cite":"463 F.3d 646","y":2006,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/463/646/","by":{"2":"26"}},{"t":"case","label":"Taylor v. Freeland & Kronz","cite":"503 U.S. 638","y":1992,"id":"1991/91-571","sc":1,"sum":"A trustee may not contest the validity of a claimed exemption after the Rule 4003(b) 30-day period has expired, even though the debtor had no colorable basis for claiming the exemption..","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"41"}},{"t":"case","label":"Tex. Dep’t of Hous. & Cmty. Affairs v. Inclusive Cmtys. Project, Inc.","cite":"135 S. Ct. 2507","y":2015,"url":"https://www.courtlistener.com/c/S.%20Ct./135/2507/","sc":1,"by":{"2":"50"}},{"t":"case","label":"Time, Inc. v. Hill","cite":"385 U.S. 374","y":1967,"id":"1965/22","sc":1,"sum":"In a 6-to-3 opinion, the Court set aside the Appellate ruling against Time because the lower court failed to instruct the jury that Time's liability was contingent upon a showing that it knowingly and recklessly published false statements about the Hill family.","sumSrc":"Oyez","by":{"2":"56"}},{"t":"case","label":"United States v. Johnston","cite":"268 U.S. 220","y":1925,"id":"scdb/1924-134","sc":1,"sum":"1. Under the provision of the \"Revenue Act of 1918,\" taxing admission fees, (Feb. 24, 1919, c. 18, § 800, 802, 40. Stat. 1057, 1120,) a person who has collected such fees at a public exhibition and is required to pay the tax to the United States is a debtor and not a bailee; so that failure to pay the tax is not indictable as an embezzlement of money of the Uilited States, within § 47 Criminal Code.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"53"}},{"t":"case","label":"United States v. Paramount Pictures, Inc.","cite":"334 U.S. 131","y":1948,"id":"scdb/1947-078","sc":1,"sum":"The United States sued to restrain violations of §§ 1 and 2 of the Sherman Act by (1) five corporations which produce motion pictures and their respective subsidiaries or affiliates which distribute and exhibit films and own or control theatres, (2) two corporations which produce motion pictures and their subsidiaries which distribute films, and (3) one corporation engaged only in the distribution of motion …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"52"}},{"t":"case","label":"Wyeth v. Levine","cite":"555 U.S. 555","y":2009,"id":"2008/06-1249","sc":1,"sum":"The Court held that federal law did not preempt state law in a personal injury action against a drug manufacturer for failing to include an appropriate warning label, even where the drug in question met the Food and Drug Administration's (FDA) labeling requirements.","sumSrc":"Oyez","by":{"2":"30"}},{"t":"const","label":"Amendment I","clauses":[["establishment","Establishment Clause"],["free-exercise","Free Exercise Clause"],["free-speech","Free Speech Clause"],["free-press","Free Press Clause"],["assembly-petition","Assembly, Petition and Association"]],"text":"Congress shall make no law respecting an establishment of religion, or prohibiting the free exercise thereof; or abridging the freedom of speech, or of the press; or the right of the people peaceably to assemble, and to petition the Government for a redress of grievances.","by":{"2":"22, 37, 38, 55","4":"14"}},{"t":"const","label":"Amendment IV","clauses":[["fourth-amendment","Fourth Amendment"]],"text":"The right of the people to be secure in their persons, houses, papers, and effects, against unreasonable searches and seizures, shall not be violated, and no Warrants shall issue, but upon probable cause, supported by Oath or affirmation, and particularly describing the place to be searched, and the persons or things to be seized.","by":{"2":"56"}},{"t":"case","label":"Adams v. Page","cite":"79 A. 837","y":1911,"court":"N.H.","url":"https://www.courtlistener.com/c/A./79/837/","by":{"3":"19"}},{"t":"case","label":"American Manufacturers Mutual Ins. Co. v. Sullivan","cite":"526 U.S. 40","y":1999,"id":"1998/97-2000","sc":1,"sum":"Further, under Pennsylvania law no due process protection attaches to payment of disputed medical expenses before the reasonableness and necessity of those expenses is determined. The Act does not entitle an employee to payment of all medical treatment, but only that treatment which is reasonable and necessary.","sumSrc":"Oyez","by":{"3":"28"}},{"t":"case","label":"Bateman v. American Multi-Cinema, Inc.","cite":"623 F.3d 708","y":2010,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/623/708/","by":{"3":"40"}},{"t":"case","label":"Beaudry v. TeleCheck Services, Inc.","cite":"579 F.3d 702","y":2009,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/579/702/","by":{"3":"40"}},{"t":"case","label":"Cicelski v. Sears, Roebuck & Co.","cite":"348 N.W.2d 685","y":1984,"court":"Mich. Ct. App.","url":"https://www.courtlistener.com/c/N.W.2d/348/685/","by":{"3":"35"}},{"t":"case","label":"Cohen v. Beneficial Industrial Loan Corp.","cite":"337 U.S. 541","y":1949,"id":"scdb/1948-101","sc":1,"sum":"1. Under 28 U. S. C. § 1291, appeal may be. taken from an order of a Federal District Court denying a corporation's motion that the plaintiff in a stockholder's derivative action be required, pursuant to a state statute, to give security for reasonable expenses of the defendants, in connection with the action.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"22, 51"}},{"t":"case","label":"Democratic Central Comm. of D.C. v. Washington Metropolitan Area Transit Comm’n","cite":"84 F.3d 451","y":1996,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/84/451/","by":{"3":"21"}},{"t":"case","label":"Deposit Guaranty Nat’l Bank v. Roper","cite":"445 U.S. 326","y":1980,"id":"1979/78-904","sc":1,"ar":1,"sum":"Neither petitioner's tender nor the District Court's entry of judgment in favor of respondents over their objections mooted their private case or controversy, and their individual interest in the litigation-as distinguished from whatever may be their representative responsibilities to the putative class-is sufficient to permit their appeal of the adverse certification ruling.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"21, 22","4":"17, 18"}},{"t":"case","label":"Eisen v. Carlisle & Jacquelin","cite":"391 F.2d 555","y":1968,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/391/555/","by":{"3":"18, 20"}},{"t":"case","label":"Evans v. Abney","cite":"396 U.S. 435","y":1970,"id":"1969/60","sc":1,"sum":"The Supreme Court held that the Georgia court did no more than apply well-settled principles of Georgia law. The court had no alternative but to end the trust under Georgia’s racially neutral trust laws. There was no indication that the Georgia judges had any discriminatory intent.","sumSrc":"Oyez","by":{"3":"18"}},{"t":"case","label":"Golan v. Veritas Entertainment, LLC","cite":"2017 WL 3923162","y":2017,"court":"E.D. Mo. Sept. 7","by":{"3":"40"}},{"t":"case","label":"Gulf Oil Corp. v. Gilbert","cite":"330 U.S. 501","y":1947,"id":"scdb/1946-068","sc":1,"sum":"It did not abuse its discretion in doing so.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"25"}},{"t":"case","label":"Hecht Co. v. Bowles","cite":"321 U.S. 321","y":1944,"id":"scdb/1943-092","sc":1,"sum":"1. Under § 205 (a) of the Emergency Price Control Act of 1942, the grant of an injunction, upon application of the Administrator and a showing that the defendant has engaged in acts or practices violative of § 4 of the Act, is not mandatory but is in the discretion of the court.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"20"}},{"t":"case","label":"Internal Improvement Fund Trustees v. Greenough","cite":"105 U.S. 527","y":1881,"id":"scdb/1881-199","sc":1,"by":{"3":"22"}},{"t":"case","label":"Janus v. AFSCME, Council 31","cite":"138 S. Ct. 2448","y":2018,"id":"2017/16-1466","sc":1,"sum":"The Court decided the State of Illinois’ extraction of agency fees from nonconsenting public-sector employees violates the First Amendment; Abood v. Detroit Bd. of Ed., 431 U.S. 209 (1977), which held otherwise, was overruled.","sumSrc":"Oyez","by":{"3":"28"}},{"t":"case","label":"Kansas v. Nebraska","cite":"135 S. Ct. 1042","y":2015,"id":"2014/126-orig","sc":1,"sum":"The Court ruled that Nebraska violated a compact apportioning the water resources of the Republican River among Kansas, Nebraska and Colorado.","sumSrc":"Oyez","by":{"3":"26"}},{"t":"case","label":"Kline v. Wolf","cite":"702 F.2d 400","y":1983,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/702/400/","by":{"3":"51"}},{"t":"case","label":"New York ex rel. Koppell v. Keds Corp.","cite":"1994 WL 97201","y":1994,"court":"S.D.N.Y. Mar. 21","by":{"3":"21"}},{"t":"case","label":"Landis v. North American Co.","cite":"299 U.S. 248","y":1936,"id":"scdb/1936-018","sc":1,"sum":"(1) That to grant the stay until decision of the other case by this Court on appeal, was abuse of discretion. P. 256. (2) The question whether the stay would have been proper under the conditions which existed when it was granted, had it been granted to continue only until decision of the other case by the District Court, is a question which this Court will not decide, because the conditions have changed. P. 258. …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"25"}},{"t":"case","label":"Link v. Wabash R.R.","cite":"370 U.S. 626","y":1962,"id":"1961/422","sc":1,"sum":"The Court held that a court has the right to clear its calendar of cases that have been dormant because of inaction on the part of the plaintiff without any motion from the defense. This right has long been understood as one of the inherent powers of the court and no law explicitly restricts it.","sumSrc":"Oyez","by":{"3":"25"}},{"t":"case","label":"Local No. 93, Int’l Ass’n of Firefighters v. City of Cleveland","cite":"478 U.S. 501","y":1986,"id":"1985/84-1999","sc":1,"sum":"The Court held that section 706(g) of Title VII does not apply to relief awarded in a consent decree.","sumSrc":"Oyez","by":{"3":"26","4":"17"}},{"t":"case","label":"Low v. Buchanan","cite":"94 Ill. 76","y":1879,"url":"https://www.courtlistener.com/c/Ill./94/76/","by":{"3":"17"}},{"t":"case","label":"Luce v. United States","cite":"469 U.S. 38","y":1984,"id":"1984/83-912","sc":1,"sum":"To raise and preserve for review the claim of improper impeachment with a prior conviction, a defendant must testify. To perform the weighing of the prior conviction's probative value against its prejudicial effect, as required by Rule 609(a)(1), the reviewing court must know the precise nature of the defendant's testimony, which is unknowable when, as here, the defendant does not testify. Any possible harm flowing …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"25"}},{"t":"case","label":"Mills v. Electric Auto-Lite Co.","cite":"396 U.S. 375","y":1970,"id":"1969/64","sc":1,"sum":"Petitioners, minority shareholders of respondent Electric Auto-Lite Co., brought this action derivatively and on behalf of minority shareholders as a class to set aside a merger of Auto-Lite and the Mergenthaler Linotype Co. (which before the merger owned over half of Auto-Lite's stock). Petitioners charged that the proxy solicitation for the merger by Auto-Lite's management was materially misleading and violated § …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"23","4":"20"}},{"t":"case","label":"Mirfasihi v. Fleet Mortgage Corp.","cite":"551 F.3d 682","y":2008,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/551/682/","by":{"3":"47"}},{"t":"case","label":"Murray v. GMAC Mortgage Corp.","cite":"434 F.3d 948","y":2006,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/434/948/","by":{"3":"40","4":"9"}},{"t":"case","label":"Stone v. Chisolm","cite":"113 U.S. 302","y":1885,"id":"scdb/1884-124","sc":1,"sum":"A suit m equity is the proper remedy, in the courts of the United States, to enforce the statutory liability of directors to a creditor of a corporation, (organized under the act of the legislature of South Carolina of December 10, 1869), by reason of the debts of the corporation being in excess of the capital stock. An action at law will not'lie.","sumSrc":"Headnote (U.S. Reports)","by":{"3":"17"}},{"t":"case","label":"Supreme Tribe of Ben Hur v. Cauble","cite":"255 U.S. 356","y":1921,"id":"scdb/1920-154","sc":1,"ar":1,"sum":"1..A suit brought against a fraternal benefit.association, and its officers, by some, in-behalf.of all, of the members of a class of its beneficiaries so numerous that it would-be impracticable to join alias parties, to determine their rights as a class respecting the disposition and control of trust funds held by the association, is cognizable by the District Court, where diversity of citizenship exists between the …","sumSrc":"Headnote (U.S. Reports)","by":{"3":"17","4":"15"}},{"t":"case","label":"Texas Department of Housing & Community Affairs v. Inclusive Communities Project, Inc.","cite":"135 S. Ct. 2507","y":2015,"id":"2014/13-1371","sc":1,"sum":"The Court determined that evidence of disparate impact is sufficient to allege a claim that the defendant violated the Fair Housing Act.","sumSrc":"Oyez","by":{"3":"44"}},{"t":"case","label":"Trans Union LLC v. FTC","cite":"536 U.S. 915","y":2002,"url":"https://supreme.justia.com/cases/federal/us/536/915/","sc":1,"by":{"3":"40"}},{"t":"case","label":"United States v. Noland","cite":"517 U.S. 535","y":1996,"id":"1995/95-323","sc":1,"sum":"Announced by Justice David H. Souter, the Court ruled that giving tax-penalty claims a lower priority than other claims contradicts Congress_ scheme of priorities regarding federal bankruptcy law.","sumSrc":"Oyez","by":{"3":"20"}},{"t":"case","label":"Vecchione v. Wohlgemuth","cite":"80 F.R.D. 32","y":1978,"court":"E.D. Pa.","url":"https://www.courtlistener.com/c/F.R.D./80/32/","by":{"3":"50"}},{"t":"case","label":"West v. Randall","cite":"29 F. Cas. 718","y":1820,"court":"C.C.D.R.I.","url":"https://www.courtlistener.com/c/F.%20Cas./29/718/","sum":"Noting need to reopen cases if absent individuals objected.","sumSrc":"brief:4","by":{"3":"16","4":"15"}},{"t":"case","label":"Whitehead v. Shattuck","cite":"138 U.S. 146","y":1891,"id":"scdb/1890-100","sc":1,"sum":"The bill alleged that the plaintiff was the owner in fee of the premises, but held the title as trustee; that notwithstanding his ownership of the property and his right to its immediate possession and enjoyment, the defendants claimed title to it and were in its possession, holding the same openly and adversely to him; that their claim of title was without foundation in law or equity; and that it was made in fraud …","sumSrc":"Headnote (U.S. Reports)","by":{"3":"17"}},{"t":"case","label":"Cent. Bank of Denver, N.A. v. First Interstate Bank of Denver, N.A.","cite":"511 U.S. 164","y":1994,"id":"1993/92-854","sc":1,"sum":"The Court held that the Securities Exchange Act only prohibits manipulative or deceitful actions, and it can only be used to prosecute such actions. Since the charge of aiding and abetting is not directly covered in the statute, companies cannot be liable for such actions.","sumSrc":"Oyez","by":{"4":"5"}},{"t":"case","label":"Citizens United v. FEC","cite":"558 U.S. 310","y":2010,"id":"2008/08-205","sc":1,"sum":"The Court held that corporate funding of independent political broadcasts in elections cannot be limited under the First Amendment.","sumSrc":"Oyez","by":{"4":"8"}},{"t":"case","label":"Eichenberger v. ESPN, Inc.","cite":"876 F.3d 979","y":2017,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/876/979/","by":{"4":"25"}},{"t":"case","label":"Fraley v. Facebook, Inc.","cite":"969 F. Supp. 2d 939","y":2013,"court":"N.D. Cal.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/969/939/","by":{"4":"22, 23"}},{"t":"case","label":"Great-West Life & Annuity Ins. Co. v. Knudson","cite":"534 U.S. 204","y":2002,"id":"2001/99-1786","sc":1,"sum":"The Court held that because Great-West is seeking legal relief - the imposition of personal liability on Knudson for a contractual obligation to pay money - ERISA does not authorize this action.","sumSrc":"Oyez","by":{"4":"18"}},{"t":"case","label":"Gregory v. Helvering","cite":"293 U.S. 465","y":1935,"id":"scdb/1934-144","sc":1,"sum":"while the plan conformed to the terms of the statute, there was no reorganization within the intent of the statute.","sumSrc":"Syllabus (U.S. Reports)","by":{"4":"10"}},{"t":"case","label":"Grupo Mexicano de Desarrollo S.A. v. Alliance Bond Fund, Inc.","cite":"527 U.S. 308","y":1999,"id":"1998/98-231","sc":1,"sum":"The Court held that the District Court lacked the authority to issue a preliminary injunction preventing defendants being sued by creditors from disposing of their assets pending adjudication of the creditor's contract claim for monetary damages because such a remedy was historically unavailable from a court of equity.","sumSrc":"Oyez","by":{"4":"4"}},{"t":"case","label":"Marshall v. Deutsche Post DHL","cite":"2015 WL 5560541","y":2015,"court":"E.D.N.Y. Sept. 21","by":{"4":"25"}},{"t":"case","label":"Pedro v. Equifax, Inc.","cite":"868 F.3d 1275","y":2017,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/868/1275/","by":{"4":"25"}},{"t":"case","label":"Rumsfeld v. Forum for Academic & Institutional Rights, Inc.","cite":"547 U.S. 47","y":2006,"id":"2005/04-1152","sc":1,"ar":1,"sum":"The Supreme Court, in a unanimous opinion written by Chief Justice John Roberts, held that the Solomon Amendment regulated conduct, not speech, and was therefore constitutional. Including military recruiters in receptions and interviews does not necessarily indicate university endorsement of the recruiters, so requiring their inclusion does not constitute compelled speech in violation of the First Amendment.","sumSrc":"Oyez","by":{"4":"26"}},{"t":"case","label":"State Oil Co. v. Khan","cite":"522 U.S. 3","y":1997,"id":"1997/96-871","sc":1,"ar":1,"sum":"The Court noted that antitrust cases are typically decided by weighing the costs and benefits of restrictions in each individual case instead of by per se rules as in Albrecht . Also, there was significant precedent contradicting the assertion that all trade restrictions are illegal, and there was evidence that the effects of price-fixing are not as detrimental as the Court thought at the time of Albrecht .","sumSrc":"Oyez","by":{"4":"5, 6"}},{"t":"case","label":"Wal-Mart Stores, Inc. v. Dukes","cite":"564 U.S. 338","y":2011,"id":"2010/10-277","sc":1,"sum":"The Court held that the small group who initiated a lawsuit could not represent all of Wal-Mart's female employees, and therefore could not bring a class action lawsuit against Wal-Mart.","sumSrc":"Oyez","by":{"4":"4, 16"}},{"t":"case","label":"Yee v. City of Escondido","cite":"503 U.S. 519","y":1992,"id":"1991/90-1947","sc":1,"sum":"The Fifth Amendment's Takings Clause generally requires just compensation where the government authorizes a physical occupation of property. But where the government merely regulates the property's use, compensation is required only if considerations such as the regulation's purpose or the extent to which it deprives the owner of the property's economic use suggests that the regulation has unfairly singled out the …","sumSrc":"Syllabus (U.S. Reports)","by":{"4":"7, 8"}},{"t":"usc","label":"42 U.S.C. § 2000e-5","url":"https://www.law.cornell.edu/uscode/text/42/2000e-5","subs":["(g)"],"by":{"4":"17"}},{"t":"rule","label":"Fed. R. Civ. P. 65","url":"https://www.law.cornell.edu/rules/frcp/rule_65","by":{"4":"16"}}]};